/* Authored fragments inserted into the existing React bundle, using its runtime.
 * Public GETs only. No demo inventory, contact messages, payments or local user data.
 */
function autolinkHomeData() {
  const initial=()=>Object.fromEntries(['vehicles','suppliers','brands','models'].map(key=>[key,{data:null,error:false}]));
  const [data,setData]=T.useState(initial),[revision,setRevision]=T.useState(0);
  T.useEffect(()=>{
    let active=true;const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),15000);
    setData(initial());
    const paths={vehicles:'/autolink/public/vehicles?limit=6',suppliers:'/autolink/public/suppliers',brands:'/autolink/public/brands',models:'/autolink/public/models'};
    const work=Object.entries(paths).map(async([key,path])=>{
      try {
        const response=await fetch(path,{credentials:'omit',cache:'no-store',signal:abort.signal});
        if(!response.ok)throw Error('Public data unavailable');
        const body=await response.json();
        if(body.code!==200||!Array.isArray(body.data))throw Error('Invalid public data');
        if(active)setData(previous=>({...previous,[key]:{data:body.data,error:false}}));
      } catch {if(active)setData(previous=>({...previous,[key]:{data:null,error:true}}));}
    });
    Promise.all(work).finally(()=>clearTimeout(timeout));
    return()=>{active=false;clearTimeout(timeout);abort.abort();};
  },[revision]);
  return {...data,retry:()=>setRevision(previous=>previous+1)};
}
function autolinkHomeStatus({result,retry,empty}) {
  if(result.error)return d('div',{className:'home-data-state',role:'status',children:[n('p',{children:'Unable to load this section. Please try again.'}),n('button',{type:'button',className:'text-link',onClick:retry,children:'Retry'})]});
  if(result.data===null)return n('p',{className:'home-data-state',role:'status',children:'Loading public listings…'});
  if(!result.data.length)return n('p',{className:'home-data-state',role:'status',children:empty});
  return null;
}
